command:
$ErrorActionPreference='Stop';
git fetch origin --prune;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$branch=(git branch --show-current).Trim();
if($branch -ne 'main'){throw "Expected main branch, found $branch"};
$origin=(git rev-parse origin/main).Trim();
if($origin -ne 'd9e3b2bcab566fed47cfca168862f69bf90fbe46'){throw "origin/main moved unexpectedly: $origin"};
$expected=@(
'app/winui/file_list_state.h',
'app/winui/FileToolbar.xaml',
'app/winui/FileToolbar.xaml.h',
'app/winui/FileToolbar.xaml.cpp',
'app/winui/MainWindow.xaml',
'app/winui/m20_shell.cpp',
'src/base/ui_preferences.cpp',
'src/base/ui_session.cpp',
'app/winui/MainWindow.xaml.cpp',
'app/winui/file_detail_controller.cpp',
'tests/winui/test_m26_fluent_contract.py',
'tests/winui/test_thumbnail_contract.py',
'tests/winui/test_registered_file_type_contract.py'
);
$dirty=@(git status --porcelain);
if($dirty.Count -eq 0){throw 'Expected validated Large Icons changes.'};
$paths=@($dirty | ForEach-Object { $_.Substring(3).Replace('\','/') });
$unexpected=@($paths | Where-Object { $_ -notin $expected });
if($unexpected.Count -ne 0){$unexpected|ForEach-Object{Write-Output "UNEXPECTED_DIRTY=$_"};throw 'Unexpected dirty path before product commit.'};
git diff --check;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
git add -- $expected;
git diff --cached --check;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
git commit -m "ui: add Large Icons view";
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$product=(git rev-parse HEAD).Trim();
Write-Output "LARGE_ICONS_PRODUCT_SHA=$product";
$policy='.agent-policy/PROJECT.md';
$text=Get-Content -Raw -LiteralPath $policy;
$text=[regex]::Replace($text,'"reviewed_revision": "[0-9a-f]{40}"',('"reviewed_revision": "'+$product+'"'),1);
$needle='projection.';
$insert="projection.`r`nLarge Icons is now an accepted fifth view mode (stable value 4) with private`r`npreference/session persistence, a 64 px Shell visual path and bounded image`r`nthumbnail use. Pre-main owned GUI evidence measured fully visible items at`r`n112x128 with 120x132 pitch against the controlled Explorer Large Icons`r`nbaseline of 105x131 with 118x132 pitch; owned thumbnails were visible,`r`nthe GUI exited 0 and protected user settings remained unchanged.";
$idx=$text.IndexOf($needle);
if($idx -lt 0){throw 'Policy checkpoint insertion point missing.'};
$idx+=$needle.Length;
$text=$text.Substring(0,$idx)+$insert.Substring($needle.Length)+$text.Substring($idx);
Set-Content -LiteralPath $policy -Value $text -Encoding utf8;
git diff --check;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
cmd /c test.bat policy;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
git add -- $policy;
git commit -m "policy: review Large Icons view";
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$policySha=(git rev-parse HEAD).Trim();
Write-Output "LARGE_ICONS_POLICY_SHA=$policySha";
git fetch origin --prune;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
$origin2=(git rev-parse origin/main).Trim();
if($origin2 -ne 'd9e3b2bcab566fed47cfca168862f69bf90fbe46'){throw "origin/main moved before push: $origin2"};
git status --short;
git push origin main;
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE};
Write-Output 'LARGE_ICONS_MAIN_PUSH_PASS';
git status --short
